import pytest
import hypothesis.strategies as st
from hypothesis import given

from solution import is_palindrome


def ref_palindrome(text: str) -> bool:
    return text == text[::-1]


# --- concrete examples from the spec docstring ---

@pytest.mark.parametrize(
    "text, expected",
    [
        ("", True),
        ("aba", True),
        ("aaaaa", True),
        ("zbcd", False),
    ],
)
def test_given_docstring_examples(text, expected):
    assert is_palindrome(text) is expected


def test_empty_string_is_palindrome():
    assert is_palindrome("") is True


# --- reference-model equivalence (exact reversal, strictly from spec) ---

@given(st.text(max_size=10))
def test_equivalence_to_exact_reverse_model(text):
    assert is_palindrome(text) == ref_palindrome(text)


@given(st.text(min_size=1, max_size=5))
def test_single_character_strings_are_palindromes(text):
    # any single character equals its own reverse
    if len(text) == 1:
        assert is_palindrome(text) is True


@given(st.text(max_size=8))
def test_reverse_symmetry(text):
    assert is_palindrome(text) == is_palindrome(text[::-1])


@given(st.text(max_size=6))
def test_constructed_even_palindrome_is_true(text):
    s = text + text[::-1]
    assert ref_palindrome(s) is True
    assert is_palindrome(s) is True


@given(st.text(max_size=6))
def test_constructed_odd_palindrome_is_true(text):
    # s + c + reverse(s) is an exact palindrome for any middle char c
    s = text + "X" + text[::-1]
    assert ref_palindrome(s) is True
    assert is_palindrome(s) is True


# --- defect-finding: case, spaces, punctuation must matter ---

def test_case_sensitivity_matters():
    # exact reverse: 'Aba' != 'abA' so must be False
    assert ref_palindrome("Aba") is False
    assert is_palindrome("Aba") is False


def test_mixed_case_pair_is_not_palindrome():
    assert ref_palindrome("Aa") is False
    assert is_palindrome("Aa") is False


def test_spaces_matter():
    assert ref_palindrome("ab a") is False
    assert is_palindrome("ab a") is False


def test_punctuation_matters():
    assert ref_palindrome("ab!a") is False
    assert is_palindrome("ab!a") is False


def test_non_alnum_pair_is_not_palindrome():
    assert ref_palindrome("!?") is False
    assert is_palindrome("!?") is False


@given(st.text(alphabet=st.characters(blacklist_categories=("L", "N")), min_size=1, max_size=5))
def test_non_alnum_strings_compared_exactly(text):
    # strings with no letters/digits: spec gives no cleaning rule,
    # so they must be compared exactly
    assert is_palindrome(text) == ref_palindrome(text)


@given(st.from_regex(r"[A-Za-z]{1,5}", fullmatch=True))
def test_mixed_case_strings_compared_exactly(text):
    assert is_palindrome(text) == ref_palindrome(text)


def test_classic_sentence_is_not_exact_palindrome():
    s = "A man a plan a canal Panama"
    assert ref_palindrome(s) is False
    assert is_palindrome(s) is False


def test_return_type_is_bool():
    assert is_palindrome("aba") is True
    assert is_palindrome("zbcd") is False
    assert isinstance(is_palindrome("aba"), bool)
    assert isinstance(is_palindrome("zbcd"), bool)
